import type { Metadata } from "next";
import Link from "next/link";
import { PageHero, Section, SectionTitle } from "@/components/marketing/primitives";
import { Reveal } from "@/components/marketing/Reveal";
import { CtaBand } from "@/components/marketing/sections";
import { TOOLS, toolsByCategory, type Tool, type ToolCategory } from "@/lib/tools/catalog";
import {
  IconGlobe,
  IconNetwork,
  IconServer,
  IconLock,
  IconCode,
  IconGauge,
  IconShield,
  IconTerminal,
  IconSpark,
  IconGame,
  IconArrow,
} from "@/components/marketing/icons";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Free Networking & Developer Tools",
  description:
    "A free suite of networking, server and developer tools: Minecraft server status checker, server size calculator, ping/latency test, WHOIS, DNS lookup, port checker, SSL checker, HTTP headers, IP lookup, password & hash generators, subnet calculator, Base64, JSON formatter and UUID generator. No signup, no limits.",
  alternates: { canonical: "/tools" },
  openGraph: {
    title: "Free Networking & Developer Tools — Nxeon",
    description:
      "WHOIS, DNS, port & SSL checkers, HTTP headers, IP lookup, password/hash generators, subnet calculator, Base64, JSON formatter and more — free, in your browser.",
    url: "/tools",
    type: "website",
  },
};

const ICONS: Record<string, (p: { size?: number }) => React.ReactNode> = {
  globe: IconGlobe,
  network: IconNetwork,
  server: IconServer,
  lock: IconLock,
  code: IconCode,
  gauge: IconGauge,
  shield: IconShield,
  terminal: IconTerminal,
  spark: IconSpark,
  game: IconGame,
};

// A short kicker above each category heading. Fixes the prior bug where the
// eyebrow and the title were the same string (so each label printed twice) —
// the kicker frames the group, the title names it.
const CATEGORY_KICKER: Record<ToolCategory, string> = {
  Network: "DNS, ports & certs",
  Developer: "Everyday utilities",
  Security: "Secrets & hashing",
  Servers: "Sizing & game checks",
};

const CATEGORY_BLURB: Record<ToolCategory, string> = {
  Network: "Diagnose domains, DNS, ports and certificates — the checks you run before and after every deploy.",
  Developer: "Everyday encode/format/generate utilities that run entirely in your browser.",
  Security: "Generate strong secrets and hashes locally — nothing is ever sent to a server.",
  Servers: "Check a game server, size your next box, and measure real latency to Nxeon before you buy.",
};

function ToolCard({ tool, delay }: { tool: Tool; delay: number }) {
  const Icon = ICONS[tool.icon] ?? IconServer;
  return (
    <Reveal delay={delay} className="h-full">
      <Link
        href={`/tools/${tool.slug}`}
        className="card card-hover group flex h-full flex-col"
      >
        <div className="mb-4 inline-flex w-fit rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-3 text-brand-300 transition-transform duration-200 group-hover:scale-105">
          {Icon({ size: 22 })}
        </div>
        <h3 className="flex items-center gap-1.5 text-base font-semibold text-white">
          {tool.name}
          {!tool.serverSide && (
            <span className="rounded-full border border-emerald-500/25 bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
              In-browser
            </span>
          )}
        </h3>
        <p className="mt-2 flex-1 text-sm leading-relaxed text-slate-400">{tool.tagline}</p>
        <span className="mt-4 inline-flex items-center gap-1 text-sm font-medium text-brand-300 transition-colors group-hover:text-brand-200">
          Open tool <IconArrow size={14} />
        </span>
      </Link>
    </Reveal>
  );
}

export default function ToolsHubPage() {
  const grouped = toolsByCategory();
  const order: ToolCategory[] = ["Servers", "Network", "Developer", "Security"];

  const itemList = {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Free networking and developer tools",
    itemListElement: TOOLS.map((t, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: t.name,
      url: `${APP_URL}/tools/${t.slug}`,
    })),
  };

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(itemList) }} />

      <PageHero
        eyebrow="Free tools"
        title="Networking & developer tools,"
        highlight="free forever"
        sub={`A growing suite of ${TOOLS.length} genuinely useful utilities — WHOIS, DNS, port & SSL checks, HTTP headers, password and hash generators, subnet math and more. No signup, no limits, no tracking.`}
        primary={{ label: "Deploy a VPS", href: "/vps" }}
        secondary={{ label: "See pricing", href: "/pricing" }}
      />

      <Section tone="panel" size="sm">
        <div className="grid gap-8 text-center sm:grid-cols-3">
          <div>
            <p className="text-3xl font-bold text-white">{TOOLS.length}</p>
            <p className="mt-1 text-sm text-slate-400">Free tools</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">$0</p>
            <p className="mt-1 text-sm text-slate-400">Forever — no account needed</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">{TOOLS.filter((t) => !t.serverSide).length}</p>
            <p className="mt-1 text-sm text-slate-400">Run 100% in your browser</p>
          </div>
        </div>
      </Section>

      {order.map((cat, ci) => (
        <Section key={cat} size="lg" tone={ci % 2 === 1 ? "panel" : "base"}>
          <SectionTitle eyebrow={CATEGORY_KICKER[cat]} title={`${cat} tools`} sub={CATEGORY_BLURB[cat]} align="left" />
          <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {grouped[cat].map((t, i) => (
              <ToolCard key={t.slug} tool={t} delay={(i % 3) * 60} />
            ))}
          </div>
        </Section>
      ))}

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}
import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { Base64Tool } from "@/components/marketing/tools/Base64Tool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Free Base64 Encode & Decode — Online, UTF-8 Safe",
  description:
    "Free online Base64 encoder and decoder. Convert text to Base64 and back, fully UTF-8 safe (emoji and accents included). Runs entirely in your browser — nothing is uploaded.",
  alternates: { canonical: "/tools/base64" },
};

const faq: ToolFaq[] = [
  {
    q: "What is Base64 encoding?",
    a: "Base64 encodes binary or text data into a set of 64 ASCII characters (A–Z, a–z, 0–9, + and /). It's used to safely embed data in contexts that only handle text, such as data URLs, JSON payloads, email attachments and HTTP headers.",
  },
  {
    q: "Is Base64 encryption?",
    a: "No. Base64 is reversible encoding, not encryption — anyone can decode it. Never use it to protect secrets. Use it for transport and embedding, and use real encryption for confidentiality.",
  },
  {
    q: "Does this handle emoji and accented characters?",
    a: "Yes. It encodes via UTF-8, so emoji, accents and any Unicode text round-trip correctly — unlike naive Base64 tools that break on non-ASCII input.",
  },
  {
    q: "Is my data uploaded anywhere?",
    a: "No. Encoding and decoding happen entirely in your browser with the built-in btoa/atob and TextEncoder APIs. Nothing is sent to a server.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="base64"
        category="Developer tool"
        title="Base64 Encode & Decode"
        description="Convert text to and from Base64 instantly. Fully UTF-8 safe and 100% in your browser — your data is never uploaded."
        about={[
          {
            heading: "What is Base64?",
            body: (
              <p>
                Base64 is a way to represent arbitrary data using only printable ASCII characters. Because
                it survives systems that mangle binary or non-ASCII bytes, it's everywhere: inline images
                as data URLs, tokens and credentials in HTTP headers, small payloads inside JSON, and MIME
                email. This tool converts in both directions and correctly handles full Unicode by encoding
                through UTF-8 first.
              </p>
            ),
          },
          {
            heading: "When you'll reach for it",
            body: (
              <ul className="list-disc space-y-1 pl-5">
                <li>Decoding a JWT segment or an HTTP Basic auth header.</li>
                <li>Building a data: URL to inline a small asset.</li>
                <li>Inspecting a Base64 blob pasted from a config or API response.</li>
                <li>Encoding text to embed safely in JSON or a query string.</li>
              </ul>
            ),
          },
        ]}
        steps={[
          "Choose Encode or Decode.",
          "Paste or type your input in the top box.",
          "The result updates instantly below.",
          "Copy the output with one click.",
        ]}
        faq={faq}
        related={relatedTools("base64")}
      >
        <Base64Tool />
      </ToolShell>
    </>
  );
}
import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { LatencyTestTool } from "@/components/marketing/tools/LatencyTestTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Ping / Latency Test — Measure Your Latency to Nxeon",
  description:
    "Free browser-based ping and latency test. Measure the round-trip time from your device to the Nxeon network in real time — average, best, worst and jitter over multiple samples. No app, no login.",
  alternates: { canonical: "/tools/latency-test" },
};

const faq: ToolFaq[] = [
  {
    q: "What is latency (ping) and why does it matter?",
    a: "Latency is the round-trip time for a small request to travel from your device to a server and back, measured in milliseconds. For game servers, remote desktops, VoIP and fast websites, lower and more consistent latency means a snappier, more responsive experience.",
  },
  {
    q: "How does this test work?",
    a: "Your browser sends a series of tiny requests to a Nxeon endpoint and times how long each round trip takes, then averages them. A warm-up request is discarded first so connection setup doesn't skew the result.",
  },
  {
    q: "What is a good ping?",
    a: "Under ~40 ms is excellent, under ~80 ms is great, and under ~150 ms is fine for most uses. Values depend heavily on your distance to the server and your own connection — someone in Asia-Pacific or Europe will see far lower numbers than someone farther from both of Nxeon's real datacenters.",
  },
  {
    q: "Why is my latency high?",
    a: "Physical distance is the biggest factor — light and network hops take time. Wi-Fi, a congested connection, or a VPN also add latency. Nxeon runs two real regions today, Singapore and Falkenstein, Germany; this specific test measures your round-trip to the Nxeon website, which is served from Singapore, so it's a good proxy for Singapore-region latency but not for the Germany region specifically — we don't claim edges we don't have.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="latency-test"
        category="Server tool"
        title="Ping / Latency Test"
        description="Measure the real round-trip latency from your browser to the Nxeon network — average, best, worst and jitter, right now."
        about={[
          {
            heading: "What this latency test measures",
            body: (
              <p>
                It times a burst of small requests from <b>your browser</b> to a Nxeon endpoint and
                reports the average round-trip latency along with the best, worst and jitter (how much
                the ping varies between samples). Because it runs from your device, it reflects the
                latency you would actually experience to a server hosted with us — not a synthetic
                number from a data center near us.
              </p>
            ),
          },
          {
            heading: "Latency, honestly",
            body: (
              <p>
                Nxeon runs two real datacenters today — Singapore and Falkenstein, Germany. This
                particular test measures latency to the Nxeon website, which is served from Singapore,
                so it's a solid proxy for Singapore-region latency specifically, not necessarily for a
                server you deploy to the Germany region. If you're in Asia-Pacific you'll see low
                numbers here; if you're in Europe, expect this number to run higher than your real
                latency would be to a Germany-region server. We'd rather show you an honest, partial
                picture than pretend to a global edge network we don't operate.
              </p>
            ),
          },
        ]}
        steps={[
          "Click Start test — no install or login needed.",
          "Your browser sends a series of timed requests to Nxeon.",
          "Read your average latency, plus best, worst and jitter.",
          "Run it again any time to compare across networks or Wi-Fi vs wired.",
        ]}
        faq={faq}
        related={relatedTools("latency-test")}
      >
        <LatencyTestTool />
      </ToolShell>
    </>
  );
}
