import Link from "next/link";
import { Reveal } from "./Reveal";
import { Eyebrow } from "./primitives";
import { IconArrow } from "./icons";
import { TOOLS, type ToolCategory } from "@/lib/tools/catalog";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

/**
 * Consistent layout wrapper for every free tool page.
 *
 *  1. A PageHero-style header — eyebrow (category) + tool name + one-line pitch,
 *     over the shared `.hero-aura` glow.
 *  2. The interactive tool UI, rendered inside a branded card (the `children`).
 *  3. An SEO content block below (What is X? / How to use / FAQ) so each page has
 *     real, indexable copy to rank on — the whole point of these SEO magnets.
 *
 * Server component: interactive tool bodies are their own "use client" islands
 * passed in as children.
 */

export type SeoBlock = { heading: string; body: React.ReactNode };
export type ToolFaq = { q: string; a: string };

// schema.org's documented applicationCategory values for SoftwareApplication —
// used verbatim by WebApplicationJsonLd below. Mapped from the tool catalog's
// own ToolCategory so a new tool gets a sane default with zero extra wiring.
const APPLICATION_CATEGORY: Record<ToolCategory, string> = {
  Network: "UtilitiesApplication",
  Developer: "DeveloperApplication",
  Security: "SecurityApplication",
  Servers: "UtilitiesApplication",
};

/**
 * WebApplication structured data for a free tool page. Every field here is
 * verifiably true (it's a real, free, in-browser or API-backed utility — see
 * lib/tools/catalog.ts) — deliberately NOT paired with aggregateRating/review,
 * since no genuine rating data exists for these tools. Fabricating one would
 * violate Google's structured-data guidelines; an honest, rating-less
 * WebApplication entity is still valid markup and still reinforces the page as
 * a real piece of software rather than a thin content page.
 */
function WebApplicationJsonLd({ slug, description }: { slug: string; description: string }) {
  const tool = TOOLS.find((t) => t.slug === slug);
  if (!tool) return null;
  const data = {
    "@context": "https://schema.org",
    "@type": "WebApplication",
    name: tool.name,
    description,
    url: `${APP_URL}/tools/${slug}`,
    applicationCategory: APPLICATION_CATEGORY[tool.category],
    operatingSystem: "Any (web browser)",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    isAccessibleForFree: true,
  };
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />;
}

export function ToolShell({
  slug,
  category,
  title,
  description,
  children,
  about,
  steps,
  faq,
  related,
}: {
  /** Tool slug under /tools — looked up in the shared catalog for WebApplication schema. */
  slug: string;
  category: string;
  title: string;
  description: string;
  children: React.ReactNode;
  /** Free-form SEO sections ("What is a subnet?", etc). */
  about?: SeoBlock[];
  /** Ordered "How to use" steps. */
  steps?: string[];
  faq?: ToolFaq[];
  /** Cross-links to sibling tools for internal linking / discovery. */
  related?: { label: string; href: string }[];
}) {
  return (
    <>
      <WebApplicationJsonLd slug={slug} description={description} />
      {/* Header */}
      <section className="relative overflow-hidden">
        <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
        <div className="rail pb-10 pt-16 sm:pt-20">
          <Reveal>
            <nav className="mb-5 flex items-center gap-2 text-xs text-slate-500">
              <Link href="/tools" className="transition-colors hover:text-slate-300">
                Free tools
              </Link>
              <span aria-hidden>/</span>
              <span className="text-slate-400">{title}</span>
            </nav>
            <Eyebrow pill>{category}</Eyebrow>
            <h1 className="mt-5 max-w-3xl text-3xl font-bold leading-[1.1] tracking-tight text-white sm:text-4xl lg:text-5xl text-balance">
              {title}
            </h1>
            <p className="mt-4 max-w-2xl text-lg leading-relaxed text-slate-400">{description}</p>
          </Reveal>
        </div>
      </section>

      {/* Tool UI */}
      <section className="relative">
        <div className="rail pb-16">
          <Reveal className="card p-5 sm:p-7">{children}</Reveal>
        </div>
      </section>

      {/* SEO content */}
      {(about?.length || steps?.length || faq?.length) && (
        <section className="tone-panel py-16 sm:py-20">
          <div className="rail">
            <div className="grid gap-12 lg:grid-cols-[1.4fr_1fr]">
              <div className="space-y-10">
                {about?.map((s) => (
                  <div key={s.heading}>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">{s.heading}</h2>
                    <div className="mt-3 space-y-3 text-[15px] leading-relaxed text-slate-400">
                      {s.body}
                    </div>
                  </div>
                ))}

                {steps && steps.length > 0 && (
                  <div>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">How to use it</h2>
                    <ol className="mt-4 space-y-3">
                      {steps.map((step, i) => (
                        <li key={i} className="flex gap-3 text-[15px] leading-relaxed text-slate-300">
                          <span className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/30 bg-brand-500/10 text-xs font-semibold text-brand-200">
                            {i + 1}
                          </span>
                          <span>{step}</span>
                        </li>
                      ))}
                    </ol>
                  </div>
                )}

                {faq && faq.length > 0 && (
                  <div>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">
                      Frequently asked questions
                    </h2>
                    <div className="mt-4 space-y-3">
                      {faq.map((f) => (
                        <details key={f.q} className="card group p-4">
                          <summary className="cursor-pointer list-none text-[15px] font-semibold text-white marker:hidden">
                            <span className="flex items-center justify-between gap-3">
                              {f.q}
                              <span className="text-slate-500 transition-transform group-open:rotate-45">
                                +
                              </span>
                            </span>
                          </summary>
                          <p className="mt-3 text-[15px] leading-relaxed text-slate-400">{f.a}</p>
                        </details>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Sidebar: related tools + CTA */}
              <aside className="space-y-6">
                {related && related.length > 0 && (
                  <div className="card">
                    <p className="section-label mb-3">Related tools</p>
                    <ul className="space-y-1">
                      {related.map((r) => (
                        <li key={r.href}>
                          <Link
                            href={r.href}
                            className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 transition-colors hover:bg-white/[0.04] hover:text-white"
                          >
                            {r.label}
                            <IconArrow size={14} />
                          </Link>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                <div className="card glow-brand bg-gradient-to-br from-brand-500/10 to-accent-blue/5">
                  <h3 className="text-base font-semibold text-white">Need a real server?</h3>
                  <p className="mt-2 text-sm leading-relaxed text-slate-400">
                    Nxeon ships NVMe cloud VPS with full root access, a dedicated IPv4, and
                    one-click apps — deployed in under a minute.
                  </p>
                  <Link href="/vps" className="btn-primary mt-4 w-full">
                    Explore VPS hosting
                    <IconArrow size={15} />
                  </Link>
                </div>
              </aside>
            </div>
          </div>
        </section>
      )}
    </>
  );
}

/** JSON-LD FAQ schema helper — drop into a tool page for rich results. */
export function FaqJsonLd({ faq }: { faq: ToolFaq[] }) {
  const data = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faq.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
  return (
    <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />
  );
}

import { currentUser } from "@/lib/auth";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { AU_ICONS } from "../_aurora/icons";
import { realReviewBadges } from "./ReviewBadges";
import { PageRuntime } from "./PageRuntime";
import { HeroParticles } from "./HeroParticles";
import { APP_URL } from "@/components/marketing/StructuredData";
import { crumbs } from "../_seo/meta";

/**
 * One ported design page (generated by tools/nxm/port_pages.py): the design's
 * own markup inside `.nxm-p-<slug>`, with the per-request slots filled here —
 * nav button and "Log in" by session, real-only review badges — and the live
 * footer after it.
 */
const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;

export async function fillSlots(html: string) {
  const [user, badges] = await Promise.all([currentUser(), realReviewBadges()]);
  const navCta = user
    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;
  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
  const reviews = badges.length
    ? `<div class="nxm-reviews">${badges
        .map(
          (b) =>
            `<a href="${esc(b.href)}" target="_blank" rel="noopener noreferrer" class="nxm-review" aria-label="${b.score} out of 5 on ${b.name}, ${b.count} reviews"><span style="color:${b.star}" aria-hidden="true">★★★★★</span><b>${b.score}</b> on ${b.name} <span class="nxm-review-n">(${b.count})</span></a>`,
        )
        .join("")}</div>`
    : "";
  return html
    .replaceAll("<!--NXM:NAVCTA-->", navCta)
    .replaceAll("<!--NXM:LOGIN-->", login)
    .replaceAll("<!--NXM:REVIEWS-->", reviews);
}

/** Page data slots: `{{nxm:key}}` in the generated markup, filled from the
 *  page's loader (app/nxm/_data/<slug>.ts) with real values from the system.
 *  Keys ending in `:html` are trusted server-rendered markup; every other
 *  value is escaped. An unfilled slot throws: a page never renders with a
 *  hole or a stale number where live data belongs. */
function fillData(html: string, slots: Record<string, string>) {
  const out = html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
    if (!(key in slots)) throw new Error(`nxm: no value for slot "${key}"`);
    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
  });
  return out;
}
const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");

/** FAQ Q/A pairs straight from the page's own FAQ markup (the Aurora FAQ is
 *  `<details><summary>Q</summary><p>A</p></details>`), after slots are filled
 *  — so the FAQ rich result always says exactly what the page says. */
const text = (h: string) => h.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, " ").trim();
export function faqFromHtml(html: string) {
  const out: { q: string; a: string }[] = [];
  // the nav's mobile sheet uses <details> for its menus — never FAQ content
  const body = html.replace(/<header\b[\s\S]*?<\/header>/g, "").replace(/<nav\b[\s\S]*?<\/nav>/g, "");
  for (const m of body.matchAll(/<details[^>]*>\s*<summary[^>]*>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/g)) {
    const q = text(m[1]), a = text(m[2]);
    if (q && a) out.push({ q, a });
  }
  return out;
}

/**
 * Structured data every page gets: BreadcrumbList from its route, FAQPage
 * from its own FAQ markup, plus whatever the page loader adds (Product offers
 * from real plans, BlogPosting, SoftwareApplication…). URLs are production
 * URLs (APP_URL + route), never the /nxm staging path.
 */
function jsonLdFor(route: string, html: string, crumbName: string | undefined, extra: object[], given?: { name: string; path: string }[]) {
  const trail = given?.length ? [{ name: "Home", path: "/" }, ...given] : crumbs(route, crumbName);
  const blocks: object[] = [];
  if (route !== "/" && trail.length > 1) {
    blocks.push({
      "@context": "https://schema.org", "@type": "BreadcrumbList",
      itemListElement: trail.map((c, i) => ({ "@type": "ListItem", position: i + 1, name: c.name, item: APP_URL + (c.path === "/" ? "" : c.path) })),
    });
  }
  const faq = faqFromHtml(html);
  if (faq.length) {
    blocks.push({
      "@context": "https://schema.org", "@type": "FAQPage",
      mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
    });
  }
  return [...blocks, ...extra];
}

/** The design page's own <body> attributes, carried on the page wrapper. */
export type BodyAttrs = { cls: string; style: string; data: Record<string, string> };
function wrapperProps(slug: string, attrs?: BodyAttrs) {
  const style: Record<string, string> = {};
  for (const decl of (attrs?.style ?? "").split(";")) {
    const i = decl.indexOf(":");
    if (i > 0) style[decl.slice(0, i).trim()] = decl.slice(i + 1).trim();
  }
  const data: Record<string, string> = {};
  for (const [k, v] of Object.entries(attrs?.data ?? {})) data[`data-${k}`] = v;
  return { className: `nxm-p nxm-p-${slug}${attrs?.cls ? " " + attrs.cls : ""}`, style: style as React.CSSProperties, ...data };
}

export async function NxmPage({ slug, route, body, attrs, particles, slots, data, jsonLd, crumb, trail }: {
  slug: string; route: string; body: string; attrs?: BodyAttrs; particles?: { from: string; to: string };
  slots?: Record<string, string>; data?: unknown; jsonLd?: object[]; crumb?: string; trail?: { name: string; path: string }[];
}) {
  const [filled, display] = await Promise.all([fillSlots(body), resolveDisplayCurrency()]);
  const page = fillData(filled, slots ?? {});
  const ld = jsonLdFor(route, page, crumb, jsonLd ?? [], trail);
  const html = page
    + (data === undefined ? "" : `<script type="application/json" id="nxm-data">${jsonForScript(data)}</script>`)
    + ld.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");
  return (
    <>
      <div {...wrapperProps(slug, attrs)} dangerouslySetInnerHTML={{ __html: html }} />
      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
        <MarketingFooter />
      </CurrencyProvider>
      <PageRuntime slug={slug} />
      {particles && <HeroParticles slug={slug} from={particles.from} to={particles.to} />}
    </>
  );
}
"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { GameParticleField } from "@/components/marketing/showcase/GameParticleField";

/**
 * The live game pages' ember field (GameParticleField, reused as-is) mounted
 * into a ported page's hero — owner's pick: particles on game pages only.
 * The hero is design markup (an HTML string), so the canvas is portaled into
 * a layer inserted at the back of it: under the hero's copy, above its
 * backdrop. Respects prefers-reduced-motion (the component seeds nothing).
 */
export function HeroParticles({ slug, from, to }: { slug: string; from: string; to: string }) {
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => {
    const hero = document.querySelector<HTMLElement>(`.nxm-p-${slug} #top`);
    if (!hero) return;
    if (getComputedStyle(hero).position === "static") hero.style.position = "relative";
    hero.style.isolation = "isolate";
    const layer = document.createElement("div");
    layer.setAttribute("aria-hidden", "true");
    layer.style.cssText = "position:absolute;inset:0;z-index:-1;pointer-events:none;overflow:hidden";
    hero.prepend(layer);
    setHost(layer);
    return () => { layer.remove(); setHost(null); };
  }, [slug]);
  return host ? createPortal(<GameParticleField colorFrom={from} colorTo={to} triggerKey={slug} />, host) : null;
}
