import type { Metadata } from "next";
import { notFound } from "next/navigation";
import "./aurora.css";
import "./nxm.css";
import { AuroraRuntime } from "./_components/AuroraRuntime";

/**
 * The new marketing site, under construction. Owner's rule: nothing here goes
 * to production until the whole site is ready, so this segment renders ONLY
 * where NXEON_ENV=staging (set in /opt/nxeon-staging/.env, absent in
 * production) and is a plain 404 everywhere else, even after the code merges.
 * Everything visual is scoped under `.nxm` (see nxm.css) so it can never
 * reach the portal, admin or the live marketing pages.
 */
// No `title` here: a plain title in this layout would reset the root layout's
// "%s — Nxeon" template for every page below it. Each page sets its own SEO
// (app/nxm/_seo).
export const metadata: Metadata = {
  robots: { index: false, follow: false, nocache: true },
};

export default function NxmLayout({ children }: { children: React.ReactNode }) {
  if (process.env.NXEON_ENV !== "staging") notFound();
  return (
    <div className="nxm">
      {children}
      <AuroraRuntime />
    </div>
  );
}
"use client";

import { useState } from "react";

/** Shared UI atoms for the interactive tool components. All client-side. */

export function CopyButton({ value, label = "Copy", className = "" }: { value: string; label?: string; className?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setCopied(true);
          setTimeout(() => setCopied(false), 1400);
        } catch {
          /* clipboard unavailable */
        }
      }}
      className={`btn-secondary px-3 py-1.5 text-xs ${className}`}
      disabled={!value}
    >
      {copied ? "Copied!" : label}
    </button>
  );
}

export function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <label className="block">
      <span className="label">{label}</span>
      {children}
      {hint && <span className="mt-1 block text-xs text-slate-500">{hint}</span>}
    </label>
  );
}

export function ErrorNote({ children }: { children: React.ReactNode }) {
  if (!children) return null;
  return (
    <div className="rounded-xl border border-red-500/25 bg-red-500/10 px-4 py-3 text-sm text-red-300">
      {children}
    </div>
  );
}

export function ResultCard({
  title,
  action,
  children,
}: {
  title?: string;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
      {(title || action) && (
        <div className="mb-3 flex items-center justify-between gap-3">
          {title && <p className="section-label">{title}</p>}
          {action}
        </div>
      )}
      {children}
    </div>
  );
}

/** Key/value grid for network results. */
export function KeyValue({ rows }: { rows: [string, React.ReactNode][] }) {
  return (
    <dl className="grid grid-cols-1 gap-x-6 gap-y-2 sm:grid-cols-[max-content_1fr]">
      {rows.map(([k, v], i) => (
        <div key={i} className="contents">
          <dt className="text-xs font-medium uppercase tracking-wide text-slate-500 sm:pt-0.5">{k}</dt>
          <dd className="break-words text-sm text-slate-200">{v ?? <span className="text-slate-600">—</span>}</dd>
        </div>
      ))}
    </dl>
  );
}

/** Monospace preformatted output with a copy button. */
export function CodeOutput({ text, maxHeight = "22rem" }: { text: string; maxHeight?: string }) {
  return (
    <div className="relative">
      <div className="absolute right-2 top-2 z-10">
        <CopyButton value={text} />
      </div>
      <pre
        className="overflow-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-4 pr-16 font-mono text-[13px] leading-relaxed text-slate-300"
        style={{ maxHeight }}
      >
        {text}
      </pre>
    </div>
  );
}

export function RunButton({
  loading,
  children = "Run",
  ...rest
}: React.ButtonHTMLAttributes<HTMLButtonElement> & { loading?: boolean }) {
  return (
    <button {...rest} className="btn-primary px-5 py-2.5" disabled={loading || rest.disabled}>
      {loading ? "Working…" : children}
    </button>
  );
}

