"use client";

/**
 * SHARED TOOL TEMPLATE — free-tool page (Minecraft Server Status checker).
 *
 * The interactive tool sits front-and-center in a premium glass frame: a real
 * address/port form, a "pinging…" scan state, then an animated result panel
 * (ONLINE/OFFLINE badge, player count, version, MOTD, latency and online-now
 * chips). Rendered by both the live page (`/tools/minecraft-server-status`)
 * and the noindex preview route — the tool itself always performs a REAL
 * server-list ping against `/api/tools/mc-status`; nothing here is mocked.
 *
 * Because tool pages are top-of-funnel (and get cited by assistants), the page
 * stays clean and fast, explains how it works, cross-links related tools, and
 * converts with a prominent "deploy a server on Nxeon" CTA.
 */

import Link from "next/link";
import { useState } from "react";
import styles from "./tool.module.css";
import { RELATED_TOOLS, HOW_STEPS, TOOL_REVIEWS } from "./data";
import { IconArrow, IconBolt, IconGame, IconGauge, IconUsers, IconServer, IconNetwork } from "@/components/marketing/icons";

type Status = "idle" | "pinging" | "done" | "error";
type PingResult = {
  host: string;
  port: number;
  online: boolean;
  versionName?: string | null;
  protocol?: number | null;
  playersOnline?: number | null;
  playersMax?: number | null;
  sample?: string[];
  motd?: string;
  latencyMs?: number;
};

/* ── the tool — real server-list ping via /api/tools/mc-status ───────────── */
function McStatusTool() {
  const [host, setHost] = useState("");
  const [port, setPort] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [result, setResult] = useState<PingResult | null>(null);
  const [error, setError] = useState("");
  const [runId, setRunId] = useState(0);

  async function run(h: string, p: string) {
    if (!h.trim()) return;
    setStatus("pinging");
    setResult(null);
    setError("");
    try {
      const res = await fetch("/api/tools/mc-status", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host: h, port: p.trim() ? Number(p) : undefined }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
      setStatus("done");
      setRunId((n) => n + 1);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
      setStatus("error");
    }
  }

  const players = result?.playersOnline ?? 0;
  const playersMax = result?.playersMax ?? 0;

  return (
    <div className="relative">
      <div className="pointer-events-none absolute -inset-[1.5px] rounded-[26px] bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-70 blur-lg" aria-hidden />
      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: "radial-gradient(45% 45% at 15% 0%, rgba(59,130,246,0.16), transparent 70%), radial-gradient(45% 45% at 90% 100%, rgba(138,112,251,0.18), transparent 70%)" }}
          aria-hidden
        />
        {/* header */}
        <div className="flex items-center gap-2.5 border-b border-white/[0.06] bg-white/[0.02] px-4 py-3">
