const { chromium } = require("/root/nxeon-worktrees/marketing-nxm/node_modules/playwright");
(async () => {
  const [prefix, width, ...paths] = process.argv.slice(2);
  const browser = await chromium.launch();
  try {
    const ctx = await browser.newContext({ viewport: { width: Number(width), height: 900 }, deviceScaleFactor: 1 });
    const page = await ctx.newPage();
    await page.routeWebSocket(/webpack-hmr/, () => {});
    page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
    page.on("console", (m) => { if (m.type() === "error") console.log("CONSOLE", m.text().slice(0, 300)); });
    for (const p of paths) {
      const [path, action] = p.split("|");
      await page.goto("http://localhost:3033" + path, { waitUntil: "networkidle", timeout: 180000 });
      await page.waitForTimeout(1500);
      if (action) { await eval(action); await page.waitForTimeout(2500); }
      // reveal everything (scroll through) so in-view animations run
      await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 600) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 80)); } window.scrollTo(0, 0); });
      await page.waitForTimeout(800);
      const name = `${prefix}-${width}-${path.replace(/[^a-z0-9]+/gi, "_")}.png`;
      await page.screenshot({ path: name, fullPage: true });
      console.log("shot", name);
    }
  } finally { await browser.close(); }
})();

