/** Runs the Aurora behaviour layer (ripples, accordions, sliders, count-ups,
 *  gauges, sparklines, the animated logo, toasts) against the `.nxm` wrapper
 *  only. Mounted once per page load. */
export function AuroraRuntime() {
  useEffect(() => {
    const root = document.querySelector<HTMLElement>(".nxm");
    if (!root || root.dataset.auMounted) return;
    root.dataset.auMounted = "1";
    mountAurora(root);
