  ];
  const html = `<div class="ab-prods">${cards.map((c) => `<a class="au-card ab-prod" href="${nxmHref(c.r)}"><span class="ab-ic" data-au-icon="${c.ic}" data-grad></span><h3>${esc(c.t)}</h3><p>${esc(c.d)}</p>${from(c.c, c.per)}<span class="go">Explore <span aria-hidden="true">→</span></span></a>`).join("")}</div>`;
