import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { Metadata } from "next";
import { Fragment, isValidElement, type ReactElement, type ReactNode } from "react";
import { ToolShell } from "@/components/marketing/ToolShell";
import { HOW_STEPS, RELATED_TOOLS } from "@/components/marketing/tooltemplate/data";
import { TOOLS, relatedTools, type Tool, type ToolCategory } from "@/lib/tools/catalog";
import { APP_URL } from "@/components/marketing/StructuredData";
import { AU_ICONS } from "../_aurora/icons";
import { NXM_BASE, esc } from "./lib";

/**
 * The free tools, read from the LIVE tool pages themselves — so the new
 * pages can never drift from what the live site says.
 *
 *  - catalogue (names, taglines, categories, in-browser vs server-side): the
 *    live directory, lib/tools/catalog.ts;
 *  - SEO title/description: each live page's exported `metadata`;
 *  - hero copy, explainer sections, how-to steps, FAQ and related tools: the
 *    props the live page hands its ToolShell (every tool but one) — or, for the
 *    Minecraft status page (a bespoke landing), its explainer markup, its own
 *    SoftwareApplication/FAQPage JSON-LD and the landing's exported step/
 *    related-tool data.
 *
 * The live page's React output is serialised to HTML here with a tiny,
 * fail-closed walker: plain text elements only (p, ul, li, b, a, code…); any
 * other component makes the page throw rather than render a gap.
 */

type LivePage = { default: () => ReactNode | Promise<ReactNode>; metadata: Metadata };
const LIVE: Record<string, () => Promise<LivePage>> = {
  "base64": () => import("@/app/(marketing)/tools/base64/page") as Promise<LivePage>,
  "dns-lookup": () => import("@/app/(marketing)/tools/dns-lookup/page") as Promise<LivePage>,
  "domain-generator": () => import("@/app/(marketing)/tools/domain-generator/page") as Promise<LivePage>,
  "hash-generator": () => import("@/app/(marketing)/tools/hash-generator/page") as Promise<LivePage>,
  "http-headers": () => import("@/app/(marketing)/tools/http-headers/page") as Promise<LivePage>,
  "json-formatter": () => import("@/app/(marketing)/tools/json-formatter/page") as Promise<LivePage>,
  "latency-test": () => import("@/app/(marketing)/tools/latency-test/page") as Promise<LivePage>,
  "minecraft-server-status": () => import("@/app/(marketing)/tools/minecraft-server-status/page") as Promise<LivePage>,
  "my-ip": () => import("@/app/(marketing)/tools/my-ip/page") as Promise<LivePage>,
  "password-generator": () => import("@/app/(marketing)/tools/password-generator/page") as Promise<LivePage>,
  "port-checker": () => import("@/app/(marketing)/tools/port-checker/page") as Promise<LivePage>,
  "server-size-calculator": () => import("@/app/(marketing)/tools/server-size-calculator/page") as Promise<LivePage>,
  "ssl-checker": () => import("@/app/(marketing)/tools/ssl-checker/page") as Promise<LivePage>,
  "subnet-calculator": () => import("@/app/(marketing)/tools/subnet-calculator/page") as Promise<LivePage>,
  "uuid-generator": () => import("@/app/(marketing)/tools/uuid-generator/page") as Promise<LivePage>,
  "whois": () => import("@/app/(marketing)/tools/whois/page") as Promise<LivePage>,
  "__hub": () => import("@/app/(marketing)/tools/page") as Promise<LivePage>,
};

export function catalogTool(slug: string): Tool | undefined {
  return TOOLS.find((t) => t.slug === slug);
}

// ── links ──────────────────────────────────────────────────────────────────
/** A production route, pointed inside the staged new site when that route has
 *  been ported (its app/nxm page exists), otherwise at the live page. At
 *  launch NXM_BASE is "" and this is the identity. */
const portedCache = new Map<string, boolean>();
export function stagedHref(href: string): string {
  const m = href.match(/^(\/[^?#]*)(.*)$/);
  if (!m || !NXM_BASE) return href;
  const [, route, rest] = m;
  let ported = portedCache.get(route);
  if (ported === undefined) {
    ported = fs.existsSync(path.join(process.cwd(), "app/nxm", route === "/" ? "" : route, "page.tsx"));
    portedCache.set(route, ported);
  }
  return ported ? NXM_BASE + (route === "/" ? "" : route) + rest : href;
}

// ── React output -> HTML (fail closed) ─────────────────────────────────────
const TAGS = new Set(["p", "ul", "ol", "li", "b", "strong", "i", "em", "code", "br", "span", "div", "a", "h2", "h3", "small"]);
type El = ReactElement<Record<string, unknown> & { children?: ReactNode }>;
const kids = (n: ReactNode): ReactNode[] => (Array.isArray(n) ? n.flat(Infinity as 1) : n == null ? [] : [n]);

export function toHtml(node: ReactNode): string {
  if (node == null || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return esc(String(node));
  if (Array.isArray(node)) return node.map(toHtml).join("");
  if (!isValidElement(node)) throw new Error("nxm tools: unsupported node in live tool content");
  const el = node as El;
  const inner = toHtml(el.props.children as ReactNode);
  if (el.type === Fragment) return inner;
  const href = typeof el.props.href === "string" ? el.props.href : null;
  if (typeof el.type === "string") {
    if (!TAGS.has(el.type)) throw new Error(`nxm tools: <${el.type}> in live tool content`);
    if (el.type === "br") return "<br>";
    if (el.type === "a") return `<a href="${esc(stagedHref(href ?? "#"))}"${el.props.target ? ` target="_blank" rel="noopener noreferrer"` : ""}>${inner}</a>`;
    return `<${el.type}>${inner}</${el.type}>`;
  }
  // next/link (a client reference on the server): any component with an href
  if (href) return `<a href="${esc(stagedHref(href))}">${inner}</a>`;
  throw new Error("nxm tools: unsupported component in live tool content");
}

/** Plain text of a node (headings). */
export function toText(node: ReactNode): string {
  return toHtml(node).replace(/<[^>]+>/g, "").replace(/&#39;/g, "'").replace(/&#34;/g, '"').replace(/&#38;/g, "&").replace(/&#60;/g, "<").replace(/&#62;/g, ">").trim();
}

/** Depth-first walk over a live page's element tree (through components'
 *  children props — nothing is rendered). */
function walk(node: ReactNode, visit: (el: El, parent: El | null) => void, parent: El | null = null) {
  for (const n of kids(node)) {
    if (!isValidElement(n)) continue;
    const el = n as El;
    visit(el, parent);
    walk(el.props.children as ReactNode, visit, el);
  }
}

// ── one tool page's content ────────────────────────────────────────────────
export type ToolContent = {
  slug: string;
  tool: Tool;
  metaTitle: string;
  metaDescription: string;
  category: string;
  title: string;
  crumb: string;
  description: string;
  about: { heading: string; html: string }[];
  steps: { title?: string; body: string }[];
  faq: { q: string; a: string }[];
  related: string[]; // tool slugs
  jsonLd: object[];
  /** the live page's own conversion block, where it has one */
  cta?: { title: string; copy: string; primary: { label: string; href: string }; secondary: { label: string; href: string }; productRoute?: string };
};

const CATEGORY_LABEL: Record<ToolCategory, string> = { Network: "Network tool", Developer: "Developer tool", Security: "Security tool", Servers: "Server tool" };
// schema.org applicationCategory, exactly as the live ToolShell maps it
const APPLICATION_CATEGORY: Record<ToolCategory, string> = {
  Network: "UtilitiesApplication", Developer: "DeveloperApplication", Security: "SecurityApplication", Servers: "UtilitiesApplication",
};
const slugOfHref = (href: string) => href.replace(/^\/tools\//, "").replace(/[?#].*$/, "");

export async function toolContent(slug: string): Promise<ToolContent | null> {
  const tool = catalogTool(slug);
  const load = LIVE[slug];
  if (!tool || !load || slug.startsWith("__")) return null;
  const mod = await load();
  const metaTitle = typeof mod.metadata.title === "string" ? mod.metadata.title : null;
  const metaDescription = mod.metadata.description ?? null;
  if (!metaTitle || !metaDescription) throw new Error(`nxm tools: live /tools/${slug} has no title/description`);
  const tree = await mod.default();

  let shell: El | null = null;
  walk(tree, (el) => { if (el.type === ToolShell) shell = el; });
  if (shell) {
    const p = (shell as El).props as unknown as {
      category: string; title: string; description: string;
      about?: { heading: string; body: ReactNode }[]; steps?: string[]; faq?: { q: string; a: string }[]; related?: { href: string }[];
    };
    return {
      slug, tool, metaTitle, metaDescription,
      category: p.category, title: p.title, crumb: p.title, description: p.description,
      about: (p.about ?? []).map((b) => ({ heading: b.heading, html: toHtml(b.body) })),
      steps: (p.steps ?? []).map((s) => ({ body: s })),
      faq: p.faq ?? [],
      related: (p.related ?? relatedTools(slug)).map((r) => slugOfHref(r.href)),
      // the live ToolShell's WebApplication entity, field for field
      jsonLd: [{
        "@context": "https://schema.org", "@type": "WebApplication",
        name: tool.name, description: p.description, url: `${APP_URL}/tools/${slug}`,
        applicationCategory: APPLICATION_CATEGORY[tool.category], operatingSystem: "Any (web browser)",
        offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, isAccessibleForFree: true,
      }],
    };
  }

  // A bespoke live landing (Minecraft status): explainer blocks are the
  // <div>s holding an <h2>; FAQ + SoftwareApplication come from its own JSON-LD.
  const about: { heading: string; html: string }[] = [];
  const ld: Record<string, unknown>[] = [];
  walk(tree, (el) => {
    if (el.type === "script") {
      const raw = (el.props.dangerouslySetInnerHTML as { __html?: string } | undefined)?.__html;
      if (raw) ld.push(JSON.parse(raw));
      return;
    }
    if (el.type !== "div") return;
    const ch = kids(el.props.children as ReactNode).filter(isValidElement) as El[];
    if (ch[0]?.type === "h2") about.push({ heading: toText(ch[0].props.children as ReactNode), html: ch.slice(1).map(toHtml).join("") });
  });
  const faqLd = ld.find((b) => b["@type"] === "FAQPage") as { mainEntity: { name: string; acceptedAnswer: { text: string } }[] } | undefined;
  const app = ld.filter((b) => b["@type"] !== "FAQPage");
  if (!about.length || !faqLd || !app.length) throw new Error(`nxm tools: live /tools/${slug} content not found`);
  if (slug !== "minecraft-server-status") throw new Error(`nxm tools: no landing adapter for /tools/${slug}`);
  return {
    slug, tool, metaTitle, metaDescription,
    category: CATEGORY_LABEL[tool.category], title: tool.name, crumb: "Minecraft status",
    // the live landing's hero line (components/marketing/tooltemplate/ToolLanding.tsx)
    description: "Check if any Minecraft server is online, how many are playing, its version and ping — in one click. Free, no login, follows SRV records.",
    about,
    steps: HOW_STEPS.map((s) => ({ title: s.title, body: s.body })),
    faq: faqLd.mainEntity.map((q) => ({ q: q.name, a: q.acceptedAnswer.text })),
    related: RELATED_TOOLS.map((r) => slugOfHref(r.href)).filter((s) => catalogTool(s)),
    jsonLd: app,
    // the live landing's "Want your own?" block
    cta: {
      title: "Spin up your Minecraft server in under a minute",
      copy: "High-clock NVMe boxes, a dedicated IP, one-click modpacks and DDoS protection — deployed instantly, then run from a clean panel. Your server address for this checker is 47 seconds away.",
      primary: { label: "Deploy a Minecraft server", href: "/minecraft-server-hosting" },
      secondary: { label: "All game servers", href: "/game-servers" },
      productRoute: "minecraft",
    },
  };
}

// ── the hub's own copy (live /tools page) ──────────────────────────────────
export type HubContent = {
  metaTitle: string; metaDescription: string;
  hero: { eyebrow: string; title: string; highlight: string; sub: string };
  groups: { cat: ToolCategory; kicker: string; title: string; sub: string }[];
};

export async function hubContent(): Promise<HubContent> {
  const mod = await LIVE.__hub();
  const metaTitle = typeof mod.metadata.title === "string" ? mod.metadata.title : null;
  const metaDescription = mod.metadata.description ?? null;
  if (!metaTitle || !metaDescription) throw new Error("nxm tools: live /tools has no title/description");
  const tree = await mod.default();
  let hero: HubContent["hero"] | null = null;
  const groups: HubContent["groups"] = [];
  walk(tree, (el) => {
    const p = el.props as Record<string, unknown>;
    if (typeof p.highlight === "string" && typeof p.title === "string" && typeof p.eyebrow === "string" && typeof p.sub === "string")
      hero = { eyebrow: p.eyebrow, title: p.title, highlight: p.highlight, sub: p.sub };
    else if (typeof p.eyebrow === "string" && typeof p.title === "string" && typeof p.sub === "string" && / tools$/.test(p.title)) {
      const cat = p.title.replace(/ tools$/, "") as ToolCategory;
      if (APPLICATION_CATEGORY[cat]) groups.push({ cat, kicker: p.eyebrow, title: p.title, sub: p.sub });
    }
  });
  if (!hero || groups.length !== 4) throw new Error("nxm tools: live /tools hero/categories not found");
  return { metaTitle, metaDescription, hero, groups };
}

// ── shared markup ──────────────────────────────────────────────────────────
/** The live directory's icon keys -> the Aurora icon set. */
const ICON: Record<string, string> = {
  globe: "globe", network: "pulse", server: "server", lock: "lock", code: "terminal", gauge: "chart",
  shield: "shield", terminal: "terminal", spark: "spark", game: "game",
};
export const toolIcon = (t: Tool) => ICON[t.icon] ?? "server";
export const tile = (t: Tool) =>
  `<span class="au-tile" aria-hidden="true"><svg class="au-ic grad" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS[toolIcon(t)] ?? ""}</svg></span>`;
/** In-browser vs checked from our servers — the live directory's own flag. */
export const modeLabel = (t: Tool) => (t.serverSide ? "Live check" : "In-browser");

