import "server-only";
import { TOOLS, toolsByCategory, type ToolCategory } from "@/lib/tools/catalog";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, nxmHref, type NxmLoad } from "./lib";
import { hubContent, modeLabel, tile } from "./tools-live";

/** /tools — the free tools directory. Every card is a tool in the live
 *  catalogue (lib/tools/catalog.ts); the hero, category copy and SEO are the
 *  live /tools page's own. Search + category filtering run in page.js. */
const ORDER: ToolCategory[] = ["Servers", "Network", "Developer", "Security"]; // the live hub's section order

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const hub = await hubContent();
  const grouped = toolsByCategory();
  const inBrowser = TOOLS.filter((t) => !t.serverSide).length;
  const lead = TOOLS[0]; // the live catalogue lists its one commercial-intent tool first on purpose

  const card = (slug: string) => {
    const t = TOOLS.find((x) => x.slug === slug)!;
    const find = [t.name, t.tagline, t.category, t.slug.replace(/-/g, " ")].join(" ");
    return `<a class="au-card th-card${t === lead ? " th-card--lead" : ""}" href="${nxmHref(`/tools/${t.slug}`)}" data-find="${esc(find)}">`
      + `<div class="th-ch">${tile(t)}<div><h3>${esc(t.name)}</h3><span class="th-mode${t.serverSide ? " srv" : ""}"><i aria-hidden="true"></i>${modeLabel(t)}</span></div></div>`
      + `<p>${esc(t.tagline)}</p><span class="th-go">Open tool <span aria-hidden="true">→</span></span></a>`;
  };
  const groups = ORDER.map((cat) => {
    const g = hub.groups.find((x) => x.cat === cat);
    if (!g) throw new Error(`nxm /tools: no live copy for ${cat}`);
    return `<section class="th-grp" data-cat="${cat.toLowerCase()}" aria-labelledby="th-${cat.toLowerCase()}">`
      + `<div class="th-gh"><div><small>${esc(g.kicker)}</small><h2 id="th-${cat.toLowerCase()}">${esc(g.title)}</h2></div><p>${esc(g.sub)}</p></div>`
      + `<div class="th-grid">${grouped[cat].map((t) => card(t.slug)).join("")}</div></section>`;
  }).join("");
  const seg = [`<button type="button" aria-pressed="true" data-v="all">All</button>`,
    ...ORDER.map((c) => `<button type="button" aria-pressed="false" data-v="${c.toLowerCase()}">${esc(c)}</button>`)].join("");
  const stats = `<div class="th-stats au-glass">`
    + `<div class="th-stat"><b data-au-count="${TOOLS.length}">${TOOLS.length}</b><small>Free tools</small></div>`
    + `<div class="th-stat"><b>$0</b><small>Forever — no account needed</small></div>`
    + `<div class="th-stat"><b data-au-count="${inBrowser}">${inBrowser}</b><small>Run 100% in your browser</small></div></div>`;

  return {
    slots: {
      "hero.eyebrow": hub.hero.eyebrow, "hero.title": hub.hero.title, "hero.highlight": hub.hero.highlight, "hero.sub": hub.hero.sub,
      count: String(TOOLS.length), "stats:html": stats, "seg:html": seg, "groups:html": groups,
    },
    // the live hub's ItemList, item for item (production URLs)
    jsonLd: [{
      "@context": "https://schema.org", "@type": "ItemList", name: "Free networking and developer tools",
      itemListElement: TOOLS.map((t, i) => ({ "@type": "ListItem", position: i + 1, name: t.name, url: `${APP_URL}/tools/${t.slug}` })),
    }],
  };
}

export async function meta(_p: Record<string, string>) {
  const hub = await hubContent();
  return { title: hub.metaTitle, description: hub.metaDescription, crumb: "Free tools" };
}

