"use client";

import { useLayoutEffect, useMemo, useRef, useState } from "react";
import { WORKLOADS, formatRam, recommendPlan, requirementsFor, type PlanSpec, type Workload } from "@/lib/tools/server-sizing";
import type { CalcData, CalcPlan } from "../_data/tools-tool";

/**
 * The server size calculator on the new site, in the Aurora language.
 *
 * Same sizing model as the live tool (lib/tools/server-sizing: WORKLOADS,
 * requirementsFor, recommendPlan) — the difference is where it ends: every
 * recommendation is a REAL plan from the catalogue checkout sells (active
 * db.plan rows, and for games the family's active db.gamePlan tiers), with its
 * real price and a deploy link built by lib/deploy-intent's deployHref. The
 * page loader (app/nxm/_data/tools-tool.ts) puts that catalogue in
 * <script id="nxm-data">; nothing here is a snapshot.
 */
const GROUPS: Workload["group"][] = ["Game servers", "Web & apps", "Bots & self-hosting"];
const d = (n: number) => `$${n.toFixed(2)}`;

function readData(): CalcData["calc"] | null {
  try {
    const raw = document.getElementById("nxm-data")?.textContent;
    const v = raw ? (JSON.parse(raw) as CalcData) : null;
    return v?.calc?.vps?.length ? v.calc : null;
  } catch {
    return null;
  }
}

/** Smallest managed tier that meets the requirement, or null when none does. */
function fitTier(tiers: CalcPlan[], ramMB: number, cpu: number) {
  const byRam = [...tiers].sort((a, b) => a.ramMB - b.ramMB || a.cpu - b.cpu);
  return byRam.find((t) => t.ramMB >= ramMB && t.cpu >= cpu) ?? byRam.find((t) => t.ramMB >= ramMB) ?? null;
}

function Price({ p }: { p: CalcPlan }) {
  return p.intro != null ? (
    <div className="sc-price">
      <p><b>{d(p.intro)}</b><s>{d(p.price)}</s><span>/mo, {p.introSpan}</span></p>
      <small>Then {d(p.price)} a month</small>
    </div>
  ) : (
    <div className="sc-price">
      <p><b>{d(p.price)}</b><span>/mo</span></p>
      <small>&nbsp;</small>
    </div>
  );
}

function PlanCard({ kind, tag, plan, specs, deployLabel, rec }: { kind: string; tag: string; plan: CalcPlan; specs: string; deployLabel: string; rec: boolean }) {
  return (
    <article className={`sc-plan${rec ? " rec" : ""}`}>
      <span className="sc-tag">{tag}</span>
      <small className="sc-kind">{kind}</small>
      <h3>{plan.name}</h3>
      <p className="sc-specs">{specs}</p>
      <Price p={plan} />
      <a className={rec ? "nxm-btn au-hov" : "nxm-glassbtn"} href={plan.href}>
        <span className="nxm-bt">{deployLabel}</span>
        {rec && <span className="nxm-arw" aria-hidden="true">→</span>}
      </a>
    </article>
  );
}

export function ToolSizeCalculator() {
  const [data] = useState(readData);
  const [group, setGroup] = useState<Workload["group"]>(GROUPS[0]);
  const [workloadId, setWorkloadId] = useState(WORKLOADS[0].id);
  const workload = WORKLOADS.find((w) => w.id === workloadId) ?? WORKLOADS[0];
  const [scale, setScale] = useState<number>(workload.scaleDefault ?? 10);

  const segRef = useRef<HTMLDivElement>(null);
  const [pill, setPill] = useState<{ x: number; w: number } | null>(null);
  useLayoutEffect(() => {
    const place = () => {
      const b = segRef.current?.querySelector<HTMLButtonElement>('button[aria-pressed="true"]');
      if (b) setPill({ x: b.offsetLeft, w: b.offsetWidth });
    };
    place();
    addEventListener("resize", place);
    return () => removeEventListener("resize", place);
  }, [group]);

  function pickWorkload(id: string) {
    const w = WORKLOADS.find((x) => x.id === id) ?? WORKLOADS[0];
    setWorkloadId(id);
    setScale(w.scaleDefault ?? 10);
  }
  function pickGroup(g: Workload["group"]) {
    setGroup(g);
    const first = WORKLOADS.find((w) => w.group === g);
    if (first && workload.group !== g) pickWorkload(first.id);
  }

  const result = useMemo(() => {
    if (!data) return null;
    const req = requirementsFor(workload, scale);
    const specs: PlanSpec[] = data.vps.map((p) => ({ slug: p.id, name: p.name, cpuCores: p.cpu, ramMB: p.ramMB, diskGB: p.disk, priceCents: Math.round(p.price * 100) }));
    const vpsRec = recommendPlan(workload, scale, specs);
    const vps = vpsRec.plan ? data.vps.find((p) => p.id === vpsRec.plan!.slug) ?? null : null;
    const game = data.tiers[workload.id];
    const tier = game ? fitTier(game.tiers, req.ramMB, req.cpuCores) : null;
    const notes = [...vpsRec.notes];
    if (game && !tier) {
