.sc-seg .pill{position:absolute;top:4px;bottom:4px;left:4px;border-radius:10px;background:var(--au-glass-2),rgba(110,100,255,.28);box-shadow:inset 0 1px 0 rgba(255,255,255,.14),inset 0 0 0 1px rgba(170,160,255,.4),0 6px 18px -8px rgba(110,90,255,.9);transition:transform var(--au-med) var(--au-out),width var(--au-med) var(--au-out)}
.sc-chips{display:flex;flex-wrap:wrap;gap:8px}
.sc-chip{display:inline-flex;align-items:center;min-height:38px;padding:0 14px;border-radius:999px;border:1px solid var(--au-line-2);background:rgba(255,255,255,.04);color:var(--ink-2);font:600 .86rem var(--f-body);cursor:pointer;transition:border-color var(--au-small),background-color var(--au-small),color var(--au-small),box-shadow var(--au-med) var(--au-out)}
.sc-chip:hover{color:#fff;border-color:rgba(170,160,255,.5)}
.sc-chip[aria-pressed="true"]{color:#fff;border-color:rgba(170,150,255,.75);background:linear-gradient(100deg,rgba(62,220,242,.16),rgba(123,92,255,.26));box-shadow:0 0 22px -8px rgba(110,110,255,.9)}
.sc-chip:focus-visible,.sc-seg button:focus-visible{outline:none;box-shadow:0 0 0 2px #070B19,0 0 0 4px #9CC9FF}
.sc-scale{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end}
.sc-range{padding-top:32px}
.sc-val{margin:0;color:var(--ink-2);font-size:.95rem;white-space:nowrap}
.sc-val b{font:800 1.9rem var(--f-display);letter-spacing:-.03em;color:#fff;font-variant-numeric:tabular-nums;margin-right:4px}
.sc-none{padding:14px 16px;border-radius:14px;border:1px dashed var(--au-line-2);white-space:normal}
.sc-hint{margin:0;color:var(--ink-2);font-size:.95rem;line-height:1.6}
.sc-req{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-radius:18px;border:1px solid var(--au-line);background:rgba(6,10,26,.6);overflow:hidden}
.sc-req div{padding:20px 16px;text-align:center}
.sc-req div+div{border-left:1px solid var(--au-line)}
.sc-req b{display:block;font:800 clamp(1.6rem,3vw,2.2rem)/1 var(--f-display);letter-spacing:-.03em;background:linear-gradient(100deg,#3EDCF2,#9B6BFF);-webkit-background-clip:text;background-clip:text;color:transparent}
.sc-req small{display:block;margin-top:8px;font:600 .72rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.sc-plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}
.sc-plan{position:relative;display:flex;flex-direction:column;gap:8px;padding:22px;border-radius:20px;border:1px solid var(--au-line);background:var(--au-glass),rgba(10,15,36,.72);box-shadow:var(--au-hi)}
.sc-plan.rec{border-color:rgba(170,150,255,.5);background:radial-gradient(90% 120% at 0% 0%,rgba(123,92,255,.2),transparent 60%),var(--au-glass),rgba(10,15,36,.8);box-shadow:var(--au-hi),0 24px 50px -28px rgba(110,90,255,.9)}
.sc-tag{align-self:flex-start;padding:4px 10px;border-radius:999px;font:700 .7rem var(--f-body);letter-spacing:.04em;text-transform:uppercase;color:#CFE0FF;background:rgba(255,255,255,.06);border:1px solid var(--au-line-2)}
.sc-plan.rec .sc-tag{color:#fff;background:var(--au-grad);border-color:transparent}
.sc-kind{margin-top:6px;color:var(--muted);font-size:.84rem}
.sc-plan h3{margin:0;font-size:1.35rem;letter-spacing:-.02em;color:#fff}
.sc-specs{margin:0;color:var(--ink-2);font:500 .86rem var(--f-mono)}
.sc-price{margin:8px 0 10px}
.sc-price p{margin:0;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:.86rem}
.sc-price b{font:800 2rem var(--f-display);letter-spacing:-.03em;color:#fff}
.sc-price s{color:var(--muted)}
.sc-price small{display:block;margin-top:2px;color:var(--muted);font-size:.8rem}
.sc-plan :is(.nxm-btn,.nxm-glassbtn){margin-top:auto;justify-content:center;width:100%}
.sc-notes{margin:0;padding:14px 18px 14px 36px;border-radius:14px;border:1px solid rgba(242,182,75,.3);background:rgba(242,182,75,.08);color:#FFD9A0;font-size:.92rem;line-height:1.6;display:grid;gap:6px;list-style:disc}
.sc-foot{display:flex;justify-content:space-between;gap:16px 28px;flex-wrap:wrap;align-items:flex-end;padding-top:18px;border-top:1px solid var(--au-line)}
.sc-foot p{margin:0;max-width:62ch;color:var(--muted);font-size:.84rem;line-height:1.6}
.sc-links{display:flex;gap:18px;flex-wrap:wrap}
.sc-links a{color:#9CC9FF;font-weight:600;font-size:.9rem;text-decoration:none}.sc-links a:hover{color:#fff}
.sc-err{margin:0;color:#FFB3BD}
@media (max-width:640px){.sc-scale{grid-template-columns:1fr;gap:10px}.sc-req b{font-size:1.5rem}}
'''
open(p,'w').write(s)
EOF

