const { chromium } = require("/root/nxeon-worktrees/marketing-nxm/node_modules/playwright");
(async () => {
  const browser = await chromium.launch();
  try {
    const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
    await page.routeWebSocket(/webpack-hmr/, () => {});
    page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
    await page.goto("http://localhost:3033/nxm/tools/server-size-calculator", { waitUntil: "networkidle", timeout: 180000 });
    await page.waitForSelector(".sc-plan", { timeout: 60000 });
    const dump = async (label) => console.log(label, JSON.stringify(await page.$$eval(".sc-plan", (els) => els.map((e) => ({
      tag: e.querySelector(".sc-tag")?.textContent, name: e.querySelector("h3")?.textContent,
      price: e.querySelector(".sc-price")?.textContent, href: e.querySelector("a")?.getAttribute("href") })))),
      JSON.stringify(await page.$$eval(".sc-req b", (b) => b.map((x) => x.textContent))),
      JSON.stringify(await page.$$eval(".sc-notes li", (b) => b.map((x) => x.textContent))));
    await dump("default");
    await page.click('.sc-chip:has-text("Minecraft (modded")');
    await page.$eval('.sc-range input', (el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, "60"); el.dispatchEvent(new Event("input", { bubbles: true })); });
    await page.waitForTimeout(300); await dump("mc-modded-60");
    await page.click('.sc-chip:has-text("Palworld")'); await page.waitForTimeout(300); await dump("palworld");
    await page.click('.sc-chip:has-text("DayZ")'); await page.waitForTimeout(300); await dump("dayz");
    await page.click('.sc-seg button:has-text("Web & apps")'); await page.waitForTimeout(300); await dump("web-first");
    await page.click('.sc-chip:has-text("WordPress")');
    await page.$eval('.sc-range input', (el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, el.max); el.dispatchEvent(new Event("input", { bubbles: true })); });
    await page.waitForTimeout(300); await dump("wordpress-max");
    console.log("links", JSON.stringify(await page.$$eval(".sc-links a", (a) => a.map((x) => x.getAttribute("href")))));
    await page.locator(".tt-panel").screenshot({ path: "calc-web.jpg", type: "jpeg", quality: 60 });
  } finally { await browser.close(); }
})();

