          <PlanCard rec kind={`Managed ${workload.label} server`} tag="Recommended" plan={tier} specs={spec(tier)} deployLabel={`Deploy ${tier.name}`} />
        )}
        {vps && (
          <PlanCard
            rec={!tier}
            kind="Cloud VPS, full root"
            tag={tier ? "Or self-manage it" : result.vpsExceeds ? "Closest plan" : "Recommended"}'''
new2='''        {tier && (
          <PlanCard rec={!result.tierExceeds} kind={`Managed ${workload.label} server`} tag={result.tierExceeds ? "Closest managed tier" : "Recommended"} plan={tier} specs={spec(tier)} deployLabel={`Deploy ${tier.name}`} />
        )}
        {vps && (
          <PlanCard
            rec={!tier}
            kind="Cloud VPS, full root"
            tag={result.vpsExceeds ? "Closest plan" : tier ? "Or self-manage it" : "Recommended"}'''
assert old2 in s; s=s.replace(old2,new2)
open(p,'w').write(s)
EOF

