  "domain-generator": async () => {},
  "password-generator": async () => {},
  "my-ip": async (p) => { await p.waitForTimeout(3000); },
};
(async () => {
  const browser = await chromium.launch();
  try {
    const page = await (await browser.newContext({ viewport: { width, height: 900 } })).newPage();
